  // The twelve e-mail groups (src/lib/emailGroups.ts) as a person reads them:
  // one name and one plain-language line per group. Read on the client (the
  // /u/<token> preference centre and AccountSettings) AND on the server, by
  // emailService.ts when it builds the unsubscribe footer — which is why
  // neither this block nor `unsubscribe` below may join SERVER_ONLY_NAMESPACES.
  //
  // The EN names are load-bearing: e2e/notif-prefs.spec.ts locates the legacy
  // in-app checkboxes with a case-insensitive `hasText` substring, so a group
  // name containing "mentorship updates" or "meeting reminders" would make
  // that locator match two labels and kill the spec on strict mode. Check any
  // rename against it.
