  consent: { section: 'Privacy & consent', intro: 'You control optional data processing. These are off by default and you can change them anytime.', nameStyleLabel: 'Name on published stories:', nameStyleInitials: 'Initials only (e.g. M. E.)', nameStyleFullname: 'Full name', items: { aiCvParsing: { title: 'AI-assisted CV reading', desc: 'Allow sending your CV text to an AI provider to suggest profile fields more accurately. Without this, only on-device parsing is used. Your CV file is never shared; only extracted text is sent when you trigger a suggestion.' }, activityTracking: { title: 'Detailed activity tracking', desc: 'Allow recording which pages you visit and how long you spend, so your mentor and admins can see a detailed activity report. Off by default; only in-app navigation is recorded — never keystrokes or page content.' }, mentorDirectoryVisibility: { title: 'Listing in the mentor directory', desc: 'Show my profile in the mentee-facing mentor directory. Shown: name, expertise, languages, capacity status and bio — never your e-mail, phone or mentee list. You can withdraw at any time; your card disappears immediately.' }, talentPoolVisibility: { title: 'Visibility to companies (talent pool)', desc: 'Allow partner companies to find your profile in talent-pool search and receive match alerts for their open positions. They see your public profile (name, university, skills, target position) — never your email or phone. Off by default; you can withdraw anytime and you disappear from company search immediately.' }, aiInteractionSummary: { title: 'AI summary of interaction logs', desc: 'Allow your mentor to generate an AI summary of the interaction log they keep about your mentorship. Only the log text is sent to the AI provider — never files or contact details. Off by default.' }, testimonial: { title: 'Publishable success story (testimonial)', desc: 'An excerpt of an evaluation written by or about me may be published on promotional pages, with my name shown the way I choose below. Publishing needs BOTH sides’ consent and the author’s approval of the exact wording. I can withdraw at any time — withdrawn stories disappear immediately.' } } },
