    title: 'Privacy & data protection',
    lastUpdatedLabel: 'Last updated',
    intro: 'We store the information you provide in order to manage mentorships and internships. This notice explains what we process, why, who can see it, how long we keep it, and your rights (GDPR Arts. 13–15).',
    controllerTitle: 'Who is responsible',
    controllerBody: 'The controller for the personal data processed here is {operator}, the operator of this InternshipCRM instance. The postal address and any further contact details are published in the imprint.',
    controllerUnset: 'The controller is whoever operates this InternshipCRM instance; their details are published in this deployment’s imprint.',
    purposesTitle: 'What we use your data for',
    purposesBody: 'To operate the platform: matching mentees with mentors and companies, tracking the internship/hiring pipeline, logging interactions, scheduling and communication.',
    legalBasisTitle: 'Legal basis',
    legalBasisBody: 'Processing relies on your consent (Art. 6(1)(a)) and on the legitimate interest of running the mentorship programme (Art. 6(1)(f)). Optional processing, such as AI-assisted CV reading, always requires separate consent.',
    recipientsTitle: 'Who can see your data',
    recipientsBody: 'Depending on your role: a mentee’s profile, CV and interaction history are visible to their assigned mentor and to administrators, and — once placed — to the linked company and the referral source. Mentors and companies see only their own mentees/candidates. We never sell your data. Extracted CV text is sent to an AI provider only if you separately enable AI-assisted CV reading. On the public home page, and only after you accept marketing cookies, the live chat is loaded from tawk.to — it receives your IP address and whatever you type into the chat. Decline, or leave the chat alone, and nothing is sent to them.',
    retentionTitle: 'How long we keep it',
    retention: 'We keep your data while your account is active and no longer than necessary for the purposes above. You can delete your account at any time from settings.',
    rightsTitle: 'Your rights',
    rights: 'You have the right to access, rectify, erase, restrict and object to processing, and to data portability. You can download all your data and delete your account from your account settings at any time.',
    withdraw: 'Where processing is based on consent, you may withdraw it at any time (e.g. in Account → Privacy), without affecting processing carried out beforehand.',
    complaint: 'You have the right to lodge a complaint with a data protection supervisory authority — in Germany, the authority of your federal state (Land) or the Federal Commissioner for Data Protection (BfDI).',
