    trans5T: 'Mekanizma olarak rıza',
    trans5D: 'Herkese açık profil ile firmalara görünürlük iki ayrı onay; her biri sürümüyle kaydediliyor ve istendiği an geri alınıyor. E-posta, telefon ve doğum tarihi herkese açık profilde hiçbir koşulda görünmüyor.',
    transBeta: 'Dürüst kısmı da şu: ürün beta, küçük bir ekip geliştiriyor ve henüz kullanıcı referansımız yok. Firma tarafı elle açılan hesaplarla yürüyor. Bunu sonradan fark etmeniz yerine burada okumanızı tercih ediyoruz.',
    transLinkFeatures: 'Tüm özellikler',
