    faqTitle: 'Gerçekten sorulan sorular',
    faqFilterAll: 'Hepsi',
    faqFilterMentee: 'Mentee',
    faqFilterMentor: 'Mentor',
    faqFilterCompany: 'Firma',
    faqMentee1Q: 'Kaydolayım da bakayım, hemen kullanabilir miyim?',
    faqMentee1A: 'Hesabını e-posta doğrulamandan sonra biz açıyoruz — genelde 1 iş günü. O arada beklemen gereken bir şey yok; biz sana uygun mentoru arıyoruz.',
    faqMentee2Q: 'Ne kadar zamanımı alır, okulumla çakışır mı?',
    faqMentee2A: 'Ritmi mentorunla sen belirliyorsun; tipik akış ayda 1-2 görüşme, arada asenkron soru-cevap. Mentorlar haftalık müsait saatlerini giriyor, sen o slotlardan talep açıyorsun. Sınav haftasında ara vermek serbest.',
    faqMentee3Q: 'Kabul edilmeme ihtimalim var mı?',
    faqMentee3A: 'Öğrenci ya da yeni mezun olman yeterli. Not ortalamana, okuluna, deneyimine bakmıyoruz. Kaydını inceliyoruz çünkü sahte hesap istemiyoruz; seçme sınavı yapmıyoruz.',
    faqMentee4Q: 'CV’mi yüklersem ne oluyor?',
    faqMentee4A: 'CV’ni yalnızca mentorun ve — sen izin verirsen — ilişkili olduğun firma görür. Yapay zekâ geri bildirimi ayrı bir onaya bağlı; sen açmazsan CV’n hiçbir modele gitmez. Hesabını sildiğinde CV’n de silinir.',
    faqMentee5Q: 'Neden ücretsiz, verimi mi satıyorsunuz?',
    faqMentee5A: 'Mentee ve mentor tarafı her zaman ücretsiz. Geliri yetenek arayan firmalardan alıyoruz — senin verini değil, sana ulaşma imkânını satıyoruz ve o da ancak sen izin verirsen.',
    faqMentee6Q: 'Bana iş bulacak mısınız?',
    faqMentee6A: 'Hayır, garanti veremeyiz ve veren kimseye de inanma. Yaptığımız şu: gerçek bir işin içine sokuyoruz, ne yaptığını yazıya döküyoruz ve o yazıyı firmaya götürüyoruz.',
    faqMentor1Q: 'Vaktim yok, bir sistem daha öğrenemem.',
    faqMentor1A: 'İlk kurulum 10 dakika: takip ettiğin kişilerin adını gir. Sonrası haftada yaklaşık 10 dakika — panoyu aç, işaretlenmiş iki kişiyle ilgilen, kapat. Not yazmak istemezsen yazma; sistem yine de kimle ne zaman temas ettiğini tutar.',
    faqMentor2Q: 'Ne kadar bağlanıyorum, çıkabilir miyim?',
    faqMentor2A: 'Kaç kişiyle ilgileneceğine sen karar veriyorsun: profilinden kontenjanını belirle, dolduğunda başvuru bağlantısı yeni başvuru kabul etmez. İstediğin an yeni başvuruları tamamen duraklatabilirsin.',
    faqMentor3Q: 'Bu bir yıl sonra duruyor olacak mı?',
    faqMentor3A: 'Bunu küçük bir ekip yazıyor ve kod tamamen açık (AGPL-3.0). Kapanma riskine karşı verdiğimiz tek somut söz şu: girdiğin her kaydı tek tıkla dışa aktarabilirsin.',
    faqMentor4Q: 'Mentor olduğum dışarıda görünecek mi?',
    faqMentor4A: 'Bugün hayır. Mentor profili ve dizini planda — vaat etmeden önce yapacağız.',
    faqMentor5Q: 'Karşılığında ben ne alıyorum?',
    faqMentor5A: 'Üç şey: hatırlama yükünden kurtulmak, aynı emekle bir kişi yerine bir ekibe yol göstermek ve yarın kendi ekibine alacağın insanı aylardır tanıyor olmak.',
    faqCompany1Q: 'Ne kadar sürede ilk adayı görürüm?',
    faqCompany1A: 'Hesabınızı biz açıp mevcut stajyerlerinizi sisteme bağlıyoruz; panelde en az bir gerçek aday olmadan size link göndermiyoruz.',
    faqCompany2Q: 'Bir sistem daha mı? ATS’imiz var.',
    faqCompany2A: 'ATS’inizin yerini almıyoruz, onu besliyoruz. Salt-okunur REST API, OpenAPI şeması ve imzalı webhook’lar var — aday verinizi kendi sisteminize akıtabilirsiniz. Kimseyi kilitlemiyoruz.',
    faqCompany3Q: 'Kaça patlar?',
    faqCompany3A: 'Pilot dönemde ücretsiz. Ödeme altyapımız henüz yok; fiyatlandırmayı ilk firmalarla birlikte belirleyeceğiz.',
    faqCompany4Q: 'Bırakmak istersem verime ne olur?',
    faqCompany4A: 'İstediğiniz gün hesabınızı ve verinizi siliyoruz. Taahhüt yok.',
    faqCompany5Q: 'Kaç aday var?',
    faqCompany5A: 'Sorun, gerçek sayıyı söyleyelim. Küçük bir sayı — ve küçük ama gerçek bir sayı, büyük ama belirsiz olandan daha değerlidir.',
    ctaMentee: 'Ücretsiz hesap aç',
    ctaMentor: 'Mentor olarak başvur',
    ctaCompany: 'Firma olarak bize yazın',
