    followup: { label: 'Takip', subject: 'Takip ediyorum', body: 'Merhaba {name},\n\nSon konuşmamızın takibini yapıyorum. İlerlemeni ve sonraki adımları paylaşır mısın?\n\nTeşekkürler' },
    outcomeNoMatch: { label: 'Sonuç · bu dönem eşleşme olmadı', subject: 'Başvurun hakkında', body: 'Merhaba {name},\n\nSeni belirsizlikte bırakmaktansa açık söylemeyi tercih ederim: bu dönem sana bir yerleştirme bulamadık. Bu, yaptığın işle ilgili bir yargı değil — kontenjan az ve uyumun iki taraf için de tutması gerekiyor.\n\nBir sonraki dönem için işe yarayacak şey şu: profilini ve becerilerini güncel tut, neyle uğraşmak istediğini bana yaz. İstersen CV’ni birlikte gözden geçirelim.\n\nAyırdığın zaman için teşekkürler; boşa gitmedi.\n\nSevgiler' },
