  cvSuggest: { button: 'CV’den öner', aiButton: 'AI ile çıkar', aiNotConfigured: 'AI çıkarımı sunucuda yapılandırılmamış.', hint: 'Yüklediğin CV’yi yerel olarak okuyup iletişim bağlantıları ve becerileri önerir. Hiçbir yere gönderilmez.', apply: 'Uygula', applyAll: 'Tümünü uygula', applied: 'Eklendi', skills: 'Beceriler', none: 'CV’de öneri bulunamadı.', failed: 'Öneriler okunamadı.', fields: { phone: 'Telefon', linkedinUrl: 'LinkedIn', githubUrl: 'GitHub', portfolioUrl: 'Portfolyo / web sitesi', fullName: 'Ad Soyad', city: 'Şehir', university: 'Üniversite', department: 'Bölüm', targetPosition: 'Hedef pozisyon' } },
  consent: { section: 'Gizlilik ve onay', intro: 'İsteğe bağlı veri işlemeyi sen kontrol edersin. Bunlar varsayılan olarak kapalıdır ve istediğin zaman değiştirebilirsin.', nameStyleLabel: 'Yayınlanan hikâyelerde ad:', nameStyleInitials: 'Yalnızca baş harfler (örn. M. E.)', nameStyleFullname: 'Tam ad', items: { aiCvParsing: { title: 'AI destekli CV okuma', desc: 'Profil alanlarını daha doğru önermek için CV metninin bir AI sağlayıcısına gönderilmesine izin ver. Bu olmadan yalnızca cihaz üzerinde ayrıştırma kullanılır. CV dosyan asla paylaşılmaz; yalnızca öneri istediğinde çıkarılan metin gönderilir.' }, activityTracking: { title: 'Ayrıntılı etkinlik takibi', desc: 'Hangi sayfaları ziyaret ettiğinin ve ne kadar süre geçirdiğinin kaydedilmesine izin ver; böylece mentorun ve yöneticiler ayrıntılı bir etkinlik raporu görebilir. Varsayılan olarak kapalıdır; yalnızca site içi gezinme kaydedilir — tuş vuruşları veya sayfa içeriği asla.' }, mentorDirectoryVisibility: { title: 'Mentor dizininde listelenme', desc: 'Profilimi mentee’lere açık mentor dizininde göster. Gösterilenler: ad, uzmanlık, diller, kapasite durumu ve tanıtım — e-posta, telefon veya mentee listen asla gösterilmez. İstediğin an geri çekebilirsin; kartın anında kaybolur.' }, talentPoolVisibility: { title: 'Şirketlere görünürlük (yetenek havuzu)', desc: 'Partner şirketlerin profilini yetenek havuzu aramasında bulmasına ve açık pozisyonları için eşleşme bildirimi almasına izin ver. Şirketler herkese açık profilini görür (ad, üniversite, yetenekler, hedef pozisyon) — e-postanı veya telefonunu asla. Varsayılan olarak kapalıdır; istediğin an geri çekebilirsin ve şirket aramasından anında çıkarsın.' }, aiInteractionSummary: { title: 'Etkileşim kayıtlarının AI özeti', desc: 'Mentörünün, mentorluğunla ilgili tuttuğu etkileşim kayıtlarının AI özetini oluşturmasına izin ver. AI sağlayıcısına yalnızca kayıt metni gönderilir — dosyalar veya iletişim bilgileri asla. Varsayılan olarak kapalıdır.' }, testimonial: { title: 'Yayınlanabilir başarı hikâyesi (referans)', desc: 'Benim yazdığım ya da hakkımda yazılan bir değerlendirmenin bir bölümü, aşağıda seçtiğim ad biçimiyle tanıtım sayfalarında yayınlanabilir. Yayın için İKİ tarafın rızası ve yazarın metni birebir onayı gerekir. İstediğim an geri alabilirim — geri alınan hikâye anında yayından düşer.' } } },
