  cvSuggest: { button: 'Aus Lebenslauf vorschlagen', aiButton: 'KI-Extraktion', aiNotConfigured: 'KI-Extraktion ist auf dem Server nicht konfiguriert.', hint: 'Liest deinen hochgeladenen Lebenslauf lokal und schlägt Kontaktlinks und Fähigkeiten vor. Es wird nichts gesendet.', apply: 'Übernehmen', applyAll: 'Alle übernehmen', applied: 'Hinzugefügt', skills: 'Fähigkeiten', none: 'Keine Vorschläge im Lebenslauf gefunden.', failed: 'Vorschläge konnten nicht gelesen werden.', fields: { phone: 'Telefon', linkedinUrl: 'LinkedIn', githubUrl: 'GitHub', portfolioUrl: 'Portfolio / Website', fullName: 'Name', city: 'Stadt', university: 'Universität', department: 'Fachbereich', targetPosition: 'Zielposition' } },
  consent: { section: 'Datenschutz & Einwilligung', intro: 'Du steuerst die optionale Datenverarbeitung. Diese ist standardmäßig aus und jederzeit änderbar.', nameStyleLabel: 'Name auf veröffentlichten Geschichten:', nameStyleInitials: 'Nur Initialen (z. B. M. E.)', nameStyleFullname: 'Vollständiger Name', items: { aiCvParsing: { title: 'KI-gestütztes Lesen des Lebenslaufs', desc: 'Erlaube, den Text deines Lebenslaufs an einen KI-Anbieter zu senden, um Profilfelder genauer vorzuschlagen. Ohne dies wird nur die Verarbeitung auf dem Gerät genutzt. Deine Lebenslauf-Datei wird nie geteilt; nur der extrahierte Text wird gesendet, wenn du einen Vorschlag auslöst.' }, activityTracking: { title: 'Detailliertes Aktivitäts-Tracking', desc: 'Erlaube die Aufzeichnung, welche Seiten du besuchst und wie lange, damit dein Mentor und Admins einen detaillierten Aktivitätsbericht sehen können. Standardmäßig aus; nur die Navigation innerhalb der App wird erfasst — niemals Tastatureingaben oder Seiteninhalte.' }, mentorDirectoryVisibility: { title: 'Eintrag im Mentorenverzeichnis', desc: 'Mein Profil im Mentee-seitigen Mentorenverzeichnis anzeigen. Sichtbar: Name, Fachgebiete, Sprachen, Kapazitätsstatus und Kurzprofil — niemals E-Mail, Telefon oder deine Mentee-Liste. Jederzeit widerrufbar; die Karte verschwindet sofort.' }, talentPoolVisibility: { title: 'Sichtbarkeit für Unternehmen (Talent-Pool)', desc: 'Erlaube Partnerunternehmen, dein Profil in der Talent-Pool-Suche zu finden und Match-Benachrichtigungen für ihre offenen Stellen zu erhalten. Sie sehen dein öffentliches Profil (Name, Universität, Fähigkeiten, Zielposition) — nie deine E-Mail oder Telefonnummer. Standardmäßig aus; du kannst jederzeit widerrufen und verschwindest sofort aus der Unternehmenssuche.' }, aiInteractionSummary: { title: 'KI-Zusammenfassung der Interaktionsprotokolle', desc: 'Erlaube deinem Mentor, eine KI-Zusammenfassung des Interaktionsprotokolls deines Mentorings zu erstellen. Nur der Protokolltext wird an den KI-Anbieter gesendet — nie Dateien oder Kontaktdaten. Standardmäßig aus.' }, testimonial: { title: 'Veröffentlichbare Erfolgsgeschichte (Testimonial)', desc: 'Ein Auszug einer von mir oder über mich geschriebenen Bewertung darf auf Werbeseiten veröffentlicht werden, mit meinem Namen in der unten gewählten Form. Die Veröffentlichung braucht die Einwilligung BEIDER Seiten und die Freigabe des exakten Wortlauts durch die Autorin/den Autor. Ich kann jederzeit widerrufen — widerrufene Geschichten verschwinden sofort.' } } },
