    purposesBody: 'Zum Betrieb der Plattform: Zuordnung von Mentees zu Mentoren und Unternehmen, Verfolgung der Praktikums-/Einstellungs-Pipeline, Protokollierung von Interaktionen, Terminplanung und Kommunikation.',
    legalBasisTitle: 'Rechtsgrundlage',
    legalBasisBody: 'Die Verarbeitung stützt sich auf deine Einwilligung (Art. 6(1)(a)) und auf das berechtigte Interesse am Betrieb des Mentoring-Programms (Art. 6(1)(f)). Optionale Verarbeitung wie KI-gestütztes Lesen des Lebenslaufs erfordert stets eine gesonderte Einwilligung.',
    recipientsTitle: 'Wer deine Daten sehen kann',
    recipientsBody: 'Je nach Rolle: Profil, Lebenslauf und Interaktionsverlauf eines Mentees sind für den zugewiesenen Mentor und für Administratoren sichtbar und — nach Vermittlung — für das verknüpfte Unternehmen und die Quelle (Empfehlung). Mentoren und Unternehmen sehen nur ihre eigenen Mentees/Kandidaten. Wir verkaufen deine Daten nicht. Extrahierter Lebenslauftext wird nur an einen KI-Anbieter gesendet, wenn du das KI-gestützte Lesen gesondert aktivierst. Auf der öffentlichen Startseite wird der Live-Chat nur nach Zustimmung zu Marketing-Cookies von tawk.to geladen; dabei erhält tawk.to deine IP-Adresse und alles, was du in den Chat schreibst. Lehnst du ab oder nutzt den Chat nicht, wird nichts an sie übermittelt.',
    retentionTitle: 'Wie lange wir sie aufbewahren',
    retention: 'Wir bewahren deine Daten auf, solange dein Konto aktiv ist, und nicht länger als für die oben genannten Zwecke erforderlich. Du kannst dein Konto jederzeit in den Einstellungen löschen.',
